import json,glob,os
targets={42,43,45,46,79}
hits=[]
files=sorted(glob.glob('**/*.jsonl',recursive=True))
scanned=0
for f in files:
    try:
        with open(f) as fh:
            for i,l in enumerate(fh):
                l=l.strip()
                if not l or not l.startswith('{'): continue
                try: r=json.loads(l)
                except Exception: continue
                if not isinstance(r,dict): continue
                if r.get('Z') in targets and r.get('mode')=='restart':
                    hits.append((f,r.get('Z'),r.get('mode'),r.get('clight','-'),r.get('ent','-')))
        scanned+=1
    except Exception: pass
print('jsonl files scanned:',scanned)
print('restart-mode rows at Z in {42,43,45,46,79}:',len(hits))
for h in hits: print('  ',h)
# also: any mode, those Z, to see what walks touched them
anym={}
for f in files:
    try:
        for l in open(f):
            l=l.strip()
            if not l.startswith('{'): continue
            try: r=json.loads(l)
            except Exception: continue
            if isinstance(r,dict) and r.get('Z') in targets:
                anym.setdefault((f,r.get('mode')),set()).add(r['Z'])
    except Exception: pass
print()
print('ALL walks touching those Z (file, mode) -> Z set:')
for k in sorted(anym, key=str): print('  ',k,sorted(anym[k]))
