for z in [42,43,45,46,79]:
    for l in open(f'pack59/row{z}.jsonl'):
        l=l.strip()
        if l.startswith('{'):
            r=json.loads(l); rows[r['Z']]=r
open('pack59/ctrl137b.jsonl','w').write(''.join(json.dumps(rows[z])+'\n' for z in sorted(rows)))
print("control rows built:",sorted(rows))
cinf={json.loads(l)['Z']:json.loads(l) for l in open('pack53/cinf.jsonl') if l.strip().startswith('{')}
chain={}
for l in open('rt/nlchain.jsonl'):
    l=l.strip()
    if l.startswith('{'):
        r=json.loads(l)
        if r.get('mode')=='chain': chain[r['Z']]=r
def ru(r):
    o=r.get('order') or []
    return o[1][0] if len(o)>1 else None
print()
print("Z   CTRL c=137        CINF c=1e6       MATCH   CHAIN(sealed)    rung  d|margin|")
for z in [42,43,45,46,79]:
    c=rows[z]; i=cinf[z]; ch=chain.get(z)
    a=(c['ent'],ru(c)); b=(i['ent'],ru(i))
    m='YES' if a==b else '** NO **'
    chs=f"{ch['ent']}/{ru(ch)}" if ch else '-'
    print(f"{z:<4}{a[0]}/{a[1]:<12}{b[0]}/{b[1]:<12}{m:<8}{chs:<17}{c.get('rung')}   {abs(c['margin']-i['margin']):.5f}")
